# app.py — Memory Moment v5
#
# Two-tab Gradio app:
#   Tab 1 (Caregiver Survey): collects the structured profile of the loved one.
#   Tab 2 (Find Words): runs the fine-tuned Gemma 4 model on the compressed
#                       Context block + the caregiver's situation.
#
# Survey data lives in gr.State and is shared across tabs. The Context block
# is generated by compress_v5.compress_survey — the same canonical Python
# implementation that mirrors the JS in the form spec (parity-tested).
#
# Same file runs in two environments:
#   USE_OLLAMA=true  → talks to local Ollama on Workbench (test)
#   USE_OLLAMA unset → talks to llama-server (built from llama.cpp by Dockerfile,
#                      runs as subprocess) — this is the HF Space deploy path

import os
import re
import gradio as gr

from compress_v5 import compress_survey

USE_OLLAMA = os.getenv("USE_OLLAMA", "false").lower() == "true"
MODEL_ID = "memory-moment-v5"
MODEL_FILE = "memory-moment-v5-Q4_K_M.gguf"
HF_REPO = "michi883/memory-moment-v5-gemma4-e2b-gguf"
OLLAMA_MODEL = os.getenv("OLLAMA_MODEL", "memory-moment")
OLLAMA_URL = os.getenv("OLLAMA_URL", "http://localhost:11434")

SYSTEM_PROMPT = (
    "You help a family caregiver find words that work in a hard moment "
    "with someone they love who has memory loss. The caregiver provides "
    "context about the loved one — their relationship, voice, things they "
    "often say, what calms them, what to avoid, what they resist — "
    "followed by a situation. "
    "Produce 3 to 5 short lines the caregiver can say out loud, each "
    "tagged with a mode: 🤝 agree-and-move, 🙂 lighten, 🫱 redirect, "
    "🛑 firm-but-kind, or 🎯 distract. Use phrases from \"often says\" when "
    "they fit naturally, or paraphrase the loved one's voice when they "
    "don't. Skip modes that don't fit. Output only the lines."
)

MODE_LABELS = {
    "🤝": "Agree & move on",
    "🙂": "Lighten it",
    "🫱": "Redirect",
    "🛑": "Firm but kind",
    "🎯": "Distract",
}
MODE_EMOJIS = set(MODE_LABELS.keys())


# ───────────────────────────────────────────────────────────────────
# Backend dispatch — Ollama (Workbench) or llama-server (Space)
# (Unchanged from v4. See app_v4.py for context.)
# ───────────────────────────────────────────────────────────────────

if USE_OLLAMA:
    import httpx

    def call_model(user_prompt: str) -> str:
        try:
            response = httpx.post(
                f"{OLLAMA_URL}/api/chat",
                json={
                    "model": OLLAMA_MODEL,
                    "messages": [
                        {"role": "system", "content": SYSTEM_PROMPT},
                        {"role": "user", "content": user_prompt},
                    ],
                    "stream": False,
                    "think": False,
                    "options": {
                        "temperature": 0.75,
                        "top_p": 0.92,
                        "top_k": 40,
                        "repeat_penalty": 1.1,
                        "num_predict": 220,
                    },
                },
                timeout=120,
            )
        except httpx.HTTPError as e:
            raise RuntimeError(f"Could not reach Ollama at {OLLAMA_URL}: {e}")

        if response.status_code != 200:
            raise RuntimeError(
                f"Ollama returned HTTP {response.status_code}: {response.text[:500]}"
            )

        data = response.json()
        content = data.get("message", {}).get("content", "")
        if not content.strip():
            raise RuntimeError(
                f"Ollama returned empty content. "
                f"Model: {OLLAMA_MODEL}. "
                f"Done reason: {data.get('done_reason', 'unknown')}. "
                f"Eval count: {data.get('eval_count', 0)}. "
                f"Full response: {str(data)[:600]}"
            )
        return content

else:
    import subprocess
    import time
    import httpx
    from huggingface_hub import hf_hub_download

    LLAMA_SERVER_URL = "http://127.0.0.1:8080"

    print(f"Downloading {MODEL_FILE} from Hugging Face...")
    model_path = hf_hub_download(
        repo_id=HF_REPO,
        filename=MODEL_FILE,
        cache_dir="/home/user/.cache/huggingface",
    )
    print(f"Model at: {model_path}")

    print("Starting llama-server...")
    server_proc = subprocess.Popen([
        "llama-server",
        "-m", model_path,
        "--host", "127.0.0.1",
        "--port", "8080",
        "-c", "2048",
        "-t", "2",
        "--jinja",
    ])

    for attempt in range(60):
        try:
            r = httpx.get(f"{LLAMA_SERVER_URL}/health", timeout=2)
            if r.status_code == 200:
                print(f"llama-server ready after {attempt * 2}s.")
                break
        except Exception:
            pass
        time.sleep(2)
    else:
        raise RuntimeError("llama-server failed to start within 120 seconds")

    def call_model(user_prompt: str) -> str:
        try:
            r = httpx.post(
                f"{LLAMA_SERVER_URL}/v1/chat/completions",
                json={
                    "messages": [
                        {"role": "system", "content": SYSTEM_PROMPT},
                        {"role": "user", "content": user_prompt},
                    ],
                    "temperature": 0.75,
                    "top_p": 0.92,
                    "top_k": 40,
                    "repeat_penalty": 1.1,
                    "max_tokens": 220,
                    "stream": False,
                    "chat_template_kwargs": {"enable_thinking": False},
                },
                timeout=120,
            )
        except httpx.HTTPError as e:
            raise RuntimeError(f"Could not reach llama-server: {e}")

        if r.status_code != 200:
            raise RuntimeError(f"llama-server returned HTTP {r.status_code}: {r.text[:500]}")

        data = r.json()
        try:
            message = data["choices"][0]["message"]
            content = message.get("content", "") or ""
        except (KeyError, IndexError):
            raise RuntimeError(f"Unexpected response shape: {str(data)[:600]}")

        if not content.strip():
            reasoning = message.get("reasoning_content", "") or ""
            if reasoning.strip():
                return reasoning

        if not content.strip():
            raise RuntimeError(f"llama-server returned empty content. Full: {str(data)[:600]}")
        return content


