# ───────────────────────────────────────────────────────────────────
# Survey state helpers
# ───────────────────────────────────────────────────────────────────

def empty_survey() -> dict:
    """The starting state — what gr.State holds before anything is filled."""
    return {
        "name_used": "",
        "relationship": "",
        "phrases_she_says": [],
        "voice_tags": [],
        "important_people": [],
        "what_calms_her": [],
        "repeats_she_makes": [],
        "topics_to_avoid": [],
        "hard_times_of_day": [],
        "things_she_resists": [],
    }


def survey_is_ready(survey: dict) -> tuple[bool, list[str]]:
    """Same validation rules as the original form. Returns (ok, missing)."""
    missing = []
    if not survey.get("name_used"):
        missing.append("a name")
    if not survey.get("relationship"):
        missing.append("relationship")
    if len(survey.get("phrases_she_says", [])) < 3:
        missing.append("at least 3 phrases")
    if not survey.get("voice_tags"):
        missing.append("at least 1 voice word")
    if not survey.get("what_calms_her"):
        missing.append("at least 1 calmer")
    return (len(missing) == 0, missing)


def lines_to_list(text: str) -> list[str]:
    """Parse newline-separated textbox into a clean list."""
    return [s.strip() for s in (text or "").split("\n") if s.strip()]


def topics_to_avoid_from_text(text: str) -> list[dict]:
    """One topic per line → list of {topic_or_name: ...} dicts.
    The dict shape mirrors the form spec; v6 may add per-topic metadata.
    """
    return [{"topic_or_name": s} for s in lines_to_list(text)]


def update_survey(
    name_used: str,
    relationship: str,
    voice_tags: list,
    phrases_text: str,
    repeats_text: str,
    avoid_text: str,
    calms: list,
    hard_times: list,
    resists: list,
) -> tuple[dict, str, str]:
    """Called on every form change. Rebuilds survey state, recomputes
    Context block, returns (survey_state, context_text, status_text).
    """
    survey = {
        "name_used": (name_used or "").strip(),
        "relationship": relationship or "",
        "phrases_she_says": lines_to_list(phrases_text),
        "voice_tags": list(voice_tags or []),
        "important_people": [],  # collected nowhere in this UI; v6 work
        "what_calms_her": list(calms or []),
        "repeats_she_makes": lines_to_list(repeats_text),
        "topics_to_avoid": topics_to_avoid_from_text(avoid_text),
        "hard_times_of_day": list(hard_times or []),
        "things_she_resists": list(resists or []),
    }
    context = compress_survey(survey)
    ok, missing = survey_is_ready(survey)
    if ok:
        # Show char/token counts so caregivers see the cost of what they wrote.
        # ~4 chars/token is the standard rule of thumb for English BPE.
        chars = len(context)
        tokens = (chars + 3) // 4
        status = f"✓ ready · {chars} chars · ~{tokens} tokens"
    else:
        status = "still need: " + ", ".join(missing)
    return survey, context, status


def load_profile(profile_id: str):
    """When a sample profile is picked, return values for every form widget.

    Returns a tuple matching the ordered list of form widget outputs declared
    in the UI section below — order matters and must stay in sync.
    """
    if not profile_id or profile_id not in PROFILES:
        s = empty_survey()
        return ("", "", [], "", "", "", [], [], [])
    p = PROFILES[profile_id]
    phrases_text = "\n".join(p["phrases_she_says"])
    repeats_text = "\n".join(p["repeats_she_makes"])
    avoid_text = "\n".join(e["topic_or_name"] for e in p["topics_to_avoid"])
    return (
        p["name_used"],
        p["relationship"],
        list(p["voice_tags"]),
        phrases_text,
        repeats_text,
        avoid_text,
        list(p["what_calms_her"]),
        list(p["hard_times_of_day"]),
        list(p["things_she_resists"]),
    )


# ───────────────────────────────────────────────────────────────────
# Output parsing — unchanged from v4
# ───────────────────────────────────────────────────────────────────

def parse_lines(raw: str) -> str:
    """Convert raw model output into Markdown cards.

    Visual hierarchy:
      - Mode label (e.g. "AGREE & MOVE ON") renders as a small dimmed
        tag above each line — caption-weight, not competing for attention.
      - The line itself (e.g. "🤝 He means well.") renders as the big
        readable headline. That's what the caregiver is looking for.
    """
    if not raw or not raw.strip():
        return "_The model returned an empty response. See terminal for details._"

    cleaned = re.sub(r"<think>.*?</think>", "", raw, flags=re.DOTALL).strip()
    if not cleaned:
        cleaned = raw

    cards = []
    for line in cleaned.split("\n"):
        line = line.strip()
        if not line:
            continue
        first_emoji = None
        rest = ""
        for emoji in MODE_EMOJIS:
            if line.startswith(emoji):
                first_emoji = emoji
                rest = line[len(emoji):].strip()
                break
        if first_emoji and rest:
            label = MODE_LABELS[first_emoji].upper()
            # Inline HTML for the label gives us actual control over size /
            # opacity, which Gradio's Markdown alone doesn't (italic + small
            # tag still render at body weight).
            tag = (
                f'<div style="font-size: 0.72em; letter-spacing: 0.1em; '
                f'opacity: 0.55; margin-bottom: 0.25em;">{label}</div>'
            )
            cards.append(f"{tag}\n\n## {first_emoji} {rest}")
    if cards:
        return "\n\n".join(cards)
    return (
        f"```\n{raw.strip()}\n```\n\n"
        f"*(could not parse mode tags — raw model output above)*"
    )


# ───────────────────────────────────────────────────────────────────
# Generator (Tab 2)
# ───────────────────────────────────────────────────────────────────

def generate_lines(survey: dict, situation: str):
    """Returns (markdown_output, context_preview).

    Reads the survey from session state — that's the linkage between Tab 1
    and Tab 2. If the survey isn't ready, surface the missing-fields message
    instead of calling the model.
    """
    ok, missing = survey_is_ready(survey or {})
    if not ok:
        return (
            f"_Fill out the survey first — still need: {', '.join(missing)}._",
            compress_survey(survey or {}),
        )
    if not situation or not situation.strip():
        return "_Describe what's happening._", compress_survey(survey)

    context = compress_survey(survey)
    user_prompt = f"{context}\n\nSituation: {situation.strip()}"

    print("─" * 60)
    print("PROMPT TO MODEL:")
    print(user_prompt)
    print("─" * 60)

    try:
        raw = call_model(user_prompt)
    except Exception as e:
        return f"**Model error**\n\n```\n{e}\n```", context

    print("RAW MODEL OUTPUT:")
    print(repr(raw))
    print("─" * 60)

    return parse_lines(raw), context


def context_for_generator(survey: dict) -> str:
    """Recompute Context block when Tab 2 is loaded or survey changes."""
    return compress_survey(survey or {})


